import type { ModalProps } from "./modal.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import * as RadixDialog from "@radix-ui/react-dialog";
import { Close as CloseIcon } from "@exp-textura/icons";
import { IconButton } from "@components/icon-button";
import { Divider as DividerComponent, type DividerProps } from "@components/divider";
import { usePortalContainer } from "@hooks/use-portal-container";

import { ModalClasses, StyledModal, StyledModalOverlay } from "./modal.styles";

const ModalRoot = forwardRef<HTMLDivElement, ModalProps>(
  (
    {
      className,
      children,
      onOpenChange,
      dismissible = true,
      open,
      defaultOpen = false,
      containerElement,
      variant = "default",
      size = "sm",
      onEscapeKeyDown,
      onInteractOutside,
      onPointerDownOutside,
      onOpenAutoFocus,
      onCloseAutoFocus,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(ModalClasses.root, className);

    const { resolvedContainer, isScoped } = usePortalContainer(containerElement);

    const { trigger, content, closeIconButton } = getValidModalChildren(children);

    return (
      <RadixDialog.Root
        defaultOpen={defaultOpen}
        modal={true}
        open={open}
        onOpenChange={onOpenChange}
      >
        {trigger}
        <RadixDialog.Portal container={resolvedContainer}>
          <StyledModalOverlay
            className={ModalClasses.overlay}
            currentTheme={theme}
            data-textura-scoped={isScoped}
            styleSlots={props.styleSlots}
            variant={variant}
          />
          <StyledModal
            ref={ref}
            aria-describedby={undefined}
            className={clsx(rootClasses, ModalClasses.body, {
              [ModalClasses.sm]: size === "sm",
              [ModalClasses.md]: size === "md",
            })}
            currentTheme={theme}
            data-textura-scoped={isScoped}
            variant={variant}
            onCloseAutoFocus={onCloseAutoFocus}
            onEscapeKeyDown={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onEscapeKeyDown?.(e);
            }}
            onInteractOutside={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onInteractOutside?.(e);
            }}
            onOpenAutoFocus={onOpenAutoFocus}
            onPointerDownOutside={(e) => {
              if (!dismissible) {
                e.preventDefault();
              }
              onPointerDownOutside?.(e);
            }}
            {...props}
          >
            {content}
            {closeIconButton}
          </StyledModal>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    );
  },
);
ModalRoot.displayName = "Modal";

const Title = ({ className, children, ...props }: RadixDialog.DialogTitleProps) => (
  <RadixDialog.Title
    className={clsx(ModalClasses.title, className)}
    data-dialog-type="title"
    {...props}
  >
    {children}
  </RadixDialog.Title>
);
Title.displayName = "Modal.Title";

const Trigger = ({ children, ...props }: RadixDialog.DialogTriggerProps) => {
  return (
    <RadixDialog.Trigger data-dialog-type="trigger" {...props} asChild>
      {children}
    </RadixDialog.Trigger>
  );
};
Trigger.displayName = "Modal.Trigger";

const Close = ({ children, ...props }: RadixDialog.DialogCloseProps) => (
  <RadixDialog.Close data-dialog-type="close" {...props} asChild>
    {children}
  </RadixDialog.Close>
);
Close.displayName = "Modal.Close";

const CloseIconButton = ({
  className,
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof RadixDialog.Close>) => (
  <RadixDialog.Close
    asChild
    aria-label={props["aria-label"] || "Close dialog"}
    className={clsx(ModalClasses.closeIconButton, className)}
    data-dialog-type="close-button"
    {...props}
  >
    <IconButton buttonType="secondary">{children || <CloseIcon />}</IconButton>
  </RadixDialog.Close>
);
CloseIconButton.displayName = "Modal.CloseIconButton";

const Content = ({ className, children, ...props }: React.ComponentPropsWithoutRef<"div">) => (
  <div className={clsx(ModalClasses.content, className)} data-dialog-type="content" {...props}>
    {children}
  </div>
);
Content.displayName = "Modal.Content";

const Divider: React.FC<DividerProps> = ({ className, ...props }) => {
  return <DividerComponent className={clsx(ModalClasses.divider, className)} {...props} />;
};
Divider.displayName = "Modal.Divider";

const Footer = ({ className, children, ...props }: React.ComponentPropsWithoutRef<"div">) => (
  <footer className={clsx(ModalClasses.footer, className)} data-dialog-type="footer" {...props}>
    {children}
  </footer>
);
Footer.displayName = "Modal.Footer";

const Modal = Object.assign(ModalRoot, {
  Trigger,
  Close,
  CloseIconButton,
  Title,
  Content,
  Divider,
  Footer,
});

export default Modal;

/**
 * Utility function to validate and extract Dialog children
 * @param {React.ReactNode} children - The children of the Dialog component
 * @returns {Object} - An object containing the trigger, content, and closeIconButton elements
 * @throws Will throw an error if the validation fails
 */
const getValidModalChildren = (
  children: React.ReactNode,
): {
  trigger: React.ReactNode[];
  content: React.ReactNode[];
  closeIconButton: React.ReactNode[];
} => {
  let titleCount = 0;
  let closeIconButtonCount = 0;
  let triggerCount = 0;
  let contentCount = 0;
  let dividerCount = 0;
  let footerCount = 0;

  const trigger: React.ReactNode[] = [];
  const content: React.ReactNode[] = [];
  const closeIconButton: React.ReactNode[] = [];

  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child)) {
      const displayName = (child.type as { displayName?: string }).displayName;

      if (displayName !== "Modal.Trigger" && displayName !== "Modal.CloseIconButton") {
        content.push(child);
      }

      if (displayName === "Modal.Content") {
        contentCount++;
      } else if (displayName === "Modal.Divider") {
        dividerCount++;
      } else if (displayName === "Modal.Footer") {
        footerCount++;
      } else if (displayName === "Modal.Title") {
        titleCount++;
      } else if (displayName === "Modal.Trigger") {
        trigger.push(child);
        triggerCount++;
      } else if (displayName === "Modal.CloseIconButton") {
        closeIconButton.push(child);
        closeIconButtonCount++;
      } else {
        throw new Error(
          "<Modal> only accepts <Modal.Title>, <Modal.CloseIconButton>, <Modal.Trigger>, <Modal.Content>, <Modal.Divider> and <Modal.Footer> as children.",
        );
      }
    }
  });

  if (contentCount > 1)
    throw new Error(`<Modal> can only have one <Modal.Content>. Found ${contentCount}.`);

  if (dividerCount > 2)
    throw new Error(`<Modal> can have up to two <Modal.Divider>. Found ${dividerCount}.`);
  if (closeIconButtonCount > 1)
    throw new Error(
      `<Modal> can only have one <Modal.CloseIconButton>. Found ${closeIconButtonCount}.`,
    );
  if (footerCount > 1)
    throw new Error(`<Modal> can only have one <Modal.Footer>. Found ${footerCount}.`);
  if (titleCount > 1)
    throw new Error(`<Modal> can only have one <Modal.Title>. Found ${titleCount}.`);
  if (triggerCount > 1)
    throw new Error(`<Modal> can only have one <Modal.Trigger>. Found ${triggerCount}.`);

  return { trigger, content, closeIconButton };
};
